#!/usr/bin/env python3
"""Adds a random minecart to scenarios generated by tools/fuzz.py, like minecart-entities.py but
harsher: the minecart may start anywhere, also inside blocks and off the centre of a rail, with
larger and vertical velocities, odd rotations and fuller loads.

    tools/fuzz.py --palette tests/palettes/minecart-harsh.json --count 60 --size 7x2x7 --ticks 50 \\
                  --seed 11 --out tests/scenarios/minecart
    tests/palettes/minecart-entities-harsh.py --seed 11 tests/scenarios/minecart/fuzz-minecart-harsh-s11-*.json

The minecart is a function of the seed and the scenario's name only. TNT minecarts are left out
(they explode when they run into something, and explosions are not modelled).
"""

import argparse
import json
import os
import random
import sys

sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "..", "tools"))
import fuzz  # noqa: E402  (for the output format)

KINDS = ["minecart", "minecart", "minecart", "chest_minecart", "furnace_minecart", "hopper_minecart",
         "spawner_minecart", "command_block_minecart"]
ITEMS = [("minecraft:stone", 64), ("minecraft:ender_pearl", 16), ("minecraft:iron_sword", 1), ("minecraft:redstone", 64),
         ("minecraft:snowball", 16), ("minecraft:bucket", 16), ("minecraft:shulker_box", 1)]


def minecart(scenario, rng):
    lo, hi = scenario["box"]["min"], scenario["box"]["max"]
    rails = [b["pos"] for b in scenario.get("blocks", []) if "rail[" in b["state"]]
    mode = rng.random()
    if rails and mode < 0.45:
        x, y, z = rng.choice(rails)
        pos = [x + 0.5, y + 0.0625, z + 0.5]
    elif rails and mode < 0.65:
        x, y, z = rng.choice(rails)
        pos = [round(x + rng.random(), 3), y + rng.choice([0.0, 0.0625, 0.3, 0.99, 1.0, 1.5]), round(z + rng.random(), 3)]
    else:
        pos = [round(rng.uniform(lo[0] + 0.5, hi[0] + 0.5), 3), rng.choice([1.0, 1.0625, 1.2, 1.5, 1.875, 2.0, 2.25, 3.0, 4.5]),
               round(rng.uniform(lo[2] + 0.5, hi[2] + 0.5), 3)]
    speed = rng.choice([0.0, 0.009, 0.02, 0.1, 0.3, 0.4, 0.9, 2.5])
    motion = [round(rng.uniform(-speed, speed), 3), rng.choice([0.0, 0.0, -0.1, 0.25, 0.7, -0.6]), round(rng.uniform(-speed, speed), 3)]
    if rng.random() < 0.4:
        motion[rng.choice([0, 2])] = 0.0
    kind = rng.choice(KINDS)
    nbt = ["Motion:[%rd,%rd,%rd]" % tuple(float(v) for v in motion)]
    if rng.random() < 0.4:
        nbt.append("Rotation:[%rf,%rf]" % (float(rng.choice([-180, -90, 45, 90, 135, 170, 190, 270, 359.5, -1234.5, 100000.25])),
                                         float(rng.choice([0, 0, 30, -400]))))
    if rng.random() < 0.3:
        nbt.append("FlippedRotation:1b")
    if kind in ("chest_minecart", "hopper_minecart"):
        size = 27 if kind == "chest_minecart" else 5
        slots = rng.sample(range(size), rng.randint(0, size))
        stacks = []
        for slot in sorted(slots):
            item, most = rng.choice(ITEMS)
            stacks.append('{Slot:%db,id:"%s",count:%d}' % (slot, item, rng.choice([1, most, rng.randint(1, most)])))
        nbt.append("Items:[" + ",".join(stacks) + "]")
        if kind == "hopper_minecart":
            # An enabled hopper minecart under a container is not modelled (the model reports it).
            nbt.append("Enabled:0b")
    if kind == "furnace_minecart":
        nbt.append("PushX:%rd" % round(rng.uniform(-1, 1), 2))
        nbt.append("PushZ:%rd" % rng.choice([0.0, round(rng.uniform(-1, 1), 2)]))
        nbt.append("Fuel:%ds" % rng.choice([0, 1, 5, 40, 3600]))
    return {"type": "minecraft:" + kind, "pos": pos, "nbt": "{" + ",".join(nbt) + "}"}


def main():
    ap = argparse.ArgumentParser(description="Add a random minecart to fuzzed scenarios.")
    ap.add_argument("--seed", type=int, required=True)
    ap.add_argument("files", nargs="+")
    args = ap.parse_args()
    for path in sorted(args.files):
        with open(path) as f:
            scenario = json.load(f)
        rng = random.Random(f"{args.seed}/{scenario['name']}")
        scenario["entities"] = [minecart(scenario, rng)]
        ordered = {k: scenario[k] for k in ("name", "ticks", "box", "settings", "fill", "blocks", "entities", "actions")
                   if k in scenario}
        with open(path, "w") as f:
            f.write(fuzz.dumps(ordered))


if __name__ == "__main__":
    main()
